<script setup lang="ts">
import {ref,onMounted,computed} from 'vue'
const props=defineProps<{role:string;request:(path:string,body?:any,method?:string)=>Promise<any>;portal:(path:string,body?:any)=>Promise<any>;contactId?:number;leaseToken?:string}>()
const rows=ref<any[]>([]),count=ref(0),page=ref(1),period=ref('upcoming'),status=ref(''),busy=ref(false),error=ref(''),message=ref('')
const choices=ref<any[]>([]),choicePage=ref(1),choiceCount=ref(0),choiceSearch=ref(''),assignment=ref('')
const reportRow=ref<any>(null),performed=ref('yes'),problem=ref(false),note=ref(''),savedReport=ref<any>(null)
const editing=ref<any>(null),reason=ref(''),historyRow=ref<any>(null),history=ref<any[]>([]),historyPage=ref(1),historyCount=ref(0)
const canWrite=computed(()=>['setter','administrator'].includes(props.role))
function zonedISO(value:string|Date,zone:string){const date=new Date(value);const formatter=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'});const parts=Object.fromEntries(formatter.formatToParts(date).map(part=>[part.type,part.value]));const offset=Math.round((Date.UTC(+parts.year,+parts.month-1,+parts.day,+parts.hour,+parts.minute,+parts.second)-date.getTime())/60000);const sign=offset>=0?'+':'-';const minutes=Math.abs(offset);return `${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}:${parts.second}${sign}${String(Math.floor(minutes/60)).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`}
const zone=ref('America/Toronto'),start=ref(zonedISO(new Date(Date.now()+3600000),'America/Toronto')),end=ref(zonedISO(new Date(Date.now()+5400000),'America/Toronto'))
let requestId=crypto.randomUUID()
function resetId(){requestId=crypto.randomUUID()}
function showDate(value:string,rowZone:string){return new Intl.DateTimeFormat('fr-FR',{timeZone:rowZone,dateStyle:'medium',timeStyle:'short'}).format(new Date(value))}
async function run(action:()=>Promise<void>){busy.value=true;error.value='';message.value='';try{await action()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function load(){const result=await props.request(`appointments/?page=${page.value}&period=${period.value}&status=${status.value}${props.contactId?'&contact_id='+props.contactId:''}`);rows.value=result.results;count.value=result.count}
async function loadChoices(){const result=await props.request(`assignments/?active=true&page=${choicePage.value}&search=${encodeURIComponent(choiceSearch.value)}`);choices.value=result.results;choiceCount.value=result.count;assignment.value=''}
async function bookingProof(row:any){return (await props.portal('assurance/booking-proof/',{advisor_id:row.advisor.id,...(props.role==='administrator'?{setter_id:row.setter.id}:{})})).proof}
async function book(){await run(async()=>{const selected=choices.value.find(row=>row.id===Number(assignment.value));if(!selected)throw new Error('Choisissez une attribution active.');const proof=await bookingProof(selected);await props.request('appointments/',{contact_id:props.contactId,assignment_id:selected.id,starts_at:start.value,ends_at:end.value,timezone:zone.value,request_id:requestId,token:props.leaseToken,proof});requestId=crypto.randomUUID();page.value=1;await load();message.value='Rendez-vous interne réservé. Aucun agenda externe synchronisé.'})}
function edit(row:any){editing.value=row;zone.value=row.timezone;start.value=zonedISO(row.starts_at,row.timezone);end.value=zonedISO(row.ends_at,row.timezone);reason.value=''}
async function reschedule(){await run(async()=>{const row=editing.value;const proof=await bookingProof(row);await props.request(`appointments/${row.id}/reschedule/`,{revision:row.revision,starts_at:start.value,ends_at:end.value,timezone:zone.value,reason:reason.value,proof});editing.value=null;await load();message.value='Rendez-vous reprogrammé. Ancien créneau conservé dans l’historique.'})}
async function cancel(){await run(async()=>{const row=editing.value;await props.request(`appointments/${row.id}/cancel/`,{revision:row.revision,reason:reason.value});editing.value=null;await load();message.value='Rendez-vous annulé. Historique conservé.'})}
async function openReport(row:any){await run(async()=>{reportRow.value=row;performed.value='yes';problem.value=false;note.value='';savedReport.value=await props.request(`appointments/${row.id}/report/`)})}
async function submitReport(){await run(async()=>{await props.request(`appointments/${reportRow.value.id}/report/`,{revision:reportRow.value.revision,performed:performed.value==='yes',problem:problem.value,note:note.value});reportRow.value=null;message.value='Compte rendu enregistré.';await load()})}
async function loadHistory(){const result=await props.request(`appointments/${historyRow.value.id}/history/?page=${historyPage.value}`);history.value=result.results;historyCount.value=result.count}
onMounted(()=>run(async()=>{await load();if(canWrite.value&&props.contactId)await loadChoices()}))
</script>
<template>
<section class="appointments"><h3>{{contactId?'Rendez-vous du prospect':'Rendez-vous Assurance'}}</h3><p class="subtle">Agenda interne uniquement. Les disponibilités Google, Microsoft et Calendly ne sont pas encore consultées.</p><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="message" role="status">{{message}}</p>
<template v-if="canWrite&&contactId&&!editing"><p v-if="!leaseToken">Prenez en charge la fiche pour réserver un rendez-vous.</p><form v-else @submit.prevent="book" @input="resetId"><label>Rechercher une attribution<input v-model="choiceSearch" @keydown.enter.prevent="run(async()=>{choicePage=1;await loadChoices()})"></label><button class="secondary" type="button" :disabled="busy" @click="run(async()=>{choicePage=1;await loadChoices()})">Rechercher les conseillers attribués</button><label>Conseiller attribué<select v-model="assignment" required :disabled="busy"><option value="">Choisir une attribution</option><option v-for="row in choices" :key="row.id" :value="String(row.id)">{{role==='administrator'?row.setter.name+' → ':''}}{{row.advisor.name}}</option></select></label><div class="appointment-actions"><button type="button" class="secondary" :disabled="busy||choicePage===1" @click="run(async()=>{choicePage--;await loadChoices()})">Précédent</button><span>{{choiceCount}} attribution(s) · page {{choicePage}}</span><button type="button" class="secondary" :disabled="busy||choicePage*25>=choiceCount" @click="run(async()=>{choicePage++;await loadChoices()})">Suivant</button></div><label>Début avec décalage horaire<input v-model="start" placeholder="2026-10-21T10:00:00-04:00" required></label><label>Fin avec décalage horaire<input v-model="end" required></label><label>Fuseau IANA<input v-model="zone" placeholder="America/Toronto" required></label><small>Format ISO 8601 : date, heure et décalage correspondant au fuseau. Exemple : 2026-10-21T10:00:00-04:00 à Toronto.</small><button class="primary" :disabled="busy||!assignment">Confirmer le rendez-vous interne</button></form></template>
<form class="appointment-actions" @submit.prevent="run(async()=>{page=1;await load()})"><label>Période<select v-model="period"><option value="upcoming">À venir</option><option value="past">Passés</option><option value="">Tous</option></select></label><label>Statut<select v-model="status"><option value="">Tous</option><option value="scheduled">Planifiés</option><option value="cancelled">Annulés</option></select></label><button class="secondary" :disabled="busy">Actualiser</button></form>
<div class="table-scroll"><table><thead><tr><th>Prospect</th><th>Conseiller</th><th>Créneau</th><th>Statut</th><th>Actions</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{row.contact.name||'Sans nom'}}<small>{{row.contact.phone}}</small></td><td>{{row.advisor.name}}</td><td>{{showDate(row.starts_at,row.timezone)}}<small>Fin : {{showDate(row.ends_at,row.timezone)}} · {{row.timezone}}</small></td><td>{{row.status==='scheduled'?'Planifié':'Annulé'}}</td><td><button v-if="role==='advisor'&&row.status==='scheduled'&&Date.parse(row.ends_at)<=Date.now()" class="secondary" :disabled="busy" @click="openReport(row)">Compte rendu</button><button v-if="canWrite&&row.status==='scheduled'" class="secondary" :disabled="busy" @click="edit(row)">Gérer ce rendez-vous</button><button v-if="role==='administrator'" class="secondary" :disabled="busy" @click="run(async()=>{historyRow=row;historyPage=1;await loadHistory()})">Historique</button></td></tr><tr v-if="!rows.length"><td colspan="5">{{busy?'Chargement…':'Aucun rendez-vous dans ce périmètre.'}}</td></tr></tbody></table></div><div class="appointment-actions"><span>{{count}} rendez-vous · page {{page}}</span><button class="secondary" :disabled="busy||page===1" @click="run(async()=>{page--;await load()})">Précédent</button><button class="secondary" :disabled="busy||page*25>=count" @click="run(async()=>{page++;await load()})">Suivant</button></div>
<section v-if="editing&&canWrite"><h4>Gérer le rendez-vous {{editing.id}}</h4><form @submit.prevent="reschedule"><label>Nouveau début (ISO 8601)<input v-model="start" required></label><label>Nouvelle fin (ISO 8601)<input v-model="end" required></label><label>Fuseau IANA<input v-model="zone" required></label><label>Motif interne obligatoire (réservé à l’administration)<input v-model="reason" required maxlength="1000"></label><div class="appointment-actions"><button class="primary" :disabled="busy">Reprogrammer</button><button class="secondary" type="button" :disabled="busy||!reason.trim()" @click="cancel">Annuler le rendez-vous</button><button class="secondary" type="button" :disabled="busy" @click="editing=null">Fermer</button></div></form></section>
<section v-if="reportRow&&role==='advisor'"><h4>Compte rendu · RDV {{reportRow.id}}</h4><template v-if="savedReport"><p>Effectué : {{savedReport.performed?'Oui':'Non'}} · Problème : {{savedReport.problem?'Oui':'Non'}}</p><p>{{savedReport.note}}</p></template><form v-else @submit.prevent="submitReport"><label>Rendez-vous effectué ?<select v-model="performed"><option value="yes">Oui</option><option value="no">Non</option></select></label><label><input v-model="problem" type="checkbox">Signaler un problème</label><label>Précisions (obligatoires si Non ou problème)<textarea v-model="note" maxlength="3000" :required="performed==='no'||problem"></textarea></label><button class="primary" :disabled="busy">Enregistrer le compte rendu</button></form><button class="secondary" @click="reportRow=null">Fermer</button></section><section v-if="role==='administrator'&&historyRow"><h4>Historique du rendez-vous {{historyRow.id}}</h4><button class="secondary" @click="historyRow=null">Fermer l’historique</button><article v-for="entry in history" :key="entry.id"><strong>{{entry.action}}</strong><small>{{new Date(entry.created_at).toLocaleString('fr-FR')}} · utilisateur interne {{entry.actor_id}}</small><pre>{{JSON.stringify(entry.metadata,null,2)}}</pre></article><div class="appointment-actions"><button class="secondary" :disabled="busy||historyPage===1" @click="run(async()=>{historyPage--;await loadHistory()})">Précédent</button><span>Page {{historyPage}}</span><button class="secondary" :disabled="busy||historyPage*25>=historyCount" @click="run(async()=>{historyPage++;await loadHistory()})">Suivant</button></div></section>
</section>
</template>
<style scoped>
.appointments{margin:24px 0;padding-top:16px;border-top:1px solid #dedfce}.appointments form{display:grid;gap:14px;margin:20px 0}.appointments select{padding:12px;background:#fff;border:1px solid #dedfce;border-radius:10px}.appointment-actions{display:flex!important;gap:12px;flex-wrap:wrap;align-items:end}.appointments pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.appointments article{border-bottom:1px solid #dedfce;padding:16px 0}.appointments button:disabled{opacity:.5;cursor:not-allowed}
</style>
